import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CFuv5BrO.js";const p=JSON.parse('{"title":"Memory","description":"How Hearth accumulates correctable context without creating unsourced, unforgettable, or self-expanding memory.","frontmatter":{"title":"Memory","description":"How Hearth accumulates correctable context without creating unsourced, unforgettable, or self-expanding memory.","outline":false},"headers":[],"relativePath":"en/design/memory.md","filePath":"en/design/memory.md","lastUpdated":1795169647000}'),s={name:"en/design/memory.md"};function n(i,e,d,c,l,m){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="memory" tabindex="-1">Memory <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;Memory&quot;">​</a></h1><p class="lead">Memory is not chat history, and more memory is not automatically better. It is a constrained cache for judgment that reduces repeated questions. What gets written, when it is recalled, and how it is forgotten are all governed by visible rules.</p><h2 id="design-goals" tabindex="-1">Design goals <a class="header-anchor" href="#design-goals" aria-label="Permalink to &quot;Design goals&quot;">​</a></h2><p>The system should remember context the user provides repeatedly, preferences, project facts, and lessons from past tasks. When memory is recalled, Hearth should say where it came from, how trustworthy it is, which scope it applies to, whether it expired, and why it was used.</p><p>Memory must be correctable and forgettable. Users can inspect what the system remembers, fix errors, limit how sensitive information may be used, and confirm that deletion reached indexes, caches, and derived summaries, not just the original page.</p><p>Memory cannot become a source of truth. Task state, approvals, artifacts, and receipts come from records. Memory supplies context only; it cannot create credentials, background tasks, or a larger authorization scope.</p><h2 id="trade-offs" tabindex="-1">Trade-offs <a class="header-anchor" href="#trade-offs" aria-label="Permalink to &quot;Trade-offs&quot;">​</a></h2><p>Hearth divides memory into four types with separate lifetimes and uses.</p><table tabindex="0"><thead><tr><th>Memory type</th><th>What it stores</th><th>Lifetime and use</th></tr></thead><tbody><tr><td>Working memory</td><td>Current task constraints, temporary observations, and intermediate results</td><td>Cleared when the task ends; serves only current execution</td></tr><tr><td>Episodic memory</td><td>What happened in past tasks, results, failures, and human corrections</td><td>Kept for the medium term, summarized, and used as reference for similar work</td></tr><tr><td>Fact memory</td><td>People, projects, organizations, and stable relationships</td><td>Kept long term with source, validity period, and sensitivity</td></tr><tr><td>User model</td><td>Preferences, communication style, habits, and value boundaries</td><td>Kept long term, highly editable, and used to reduce repeated explanation</td></tr></tbody></table><p>Memory enters a candidate state before being written. The system checks source, sensitivity, duplication, conflict, and user authorization. Web pages, email, documents, and tool output can all contain misleading content, so a single appearance does not make a high-confidence fact. Highly sensitive information is not written automatically by default.</p><p>Retrieval filters by task need, applicable scope, source trust, freshness, sensitivity, and context budget. The system does not stuff all memory into one task or let different accounts and projects contaminate each other. New facts cannot silently overwrite old ones; conflicts preserve sources and ask for confirmation. Low-confidence memory cannot by itself trigger a high-risk action.</p><p>Forgetting must reach caches, the semantic index, and derived summaries. Caches need versions, invalidation, and deletion rules; forgotten content cannot be recalled again.</p><h2 id="relationship-to-the-knowledge-base" tabindex="-1">Relationship to the knowledge base <a class="header-anchor" href="#relationship-to-the-knowledge-base" aria-label="Permalink to &quot;Relationship to the knowledge base&quot;">​</a></h2><p>Hearth is the sole write authority for memory. Memory is projected into the local library tree for search and reading; deletion, forgetting, and trash remain controlled by the memory service, and rebuilding derived search data never changes memory provenance or forgetting state.</p>',14)])])}const u=t(s,[["render",n]]);export{p as __pageData,u as default};
